exercises.solution:
public class Grades {
    public static String grade(int score) {
        if (score < 0 || score > 100) return "invalid";
        if (score >= 80) return "A";
        if (score >= 65) return "B";
        if (score >= 50) return "C";
        if (score >= 40) return "D";
        return "E";
    }
}

